<?php namespace App\Livewire\Student; use App\Actions\CancelOrderAction; use App\Models\Order; use Illuminate\Foundation\Auth\Access\AuthorizesRequests; use Livewire\Attributes\Layout; use Livewire\Component; #[Layout('layouts.app')] class MyOrders extends Component { use AuthorizesRequests; public ?int $selectedOrderId = null; public function selectOrder(int $orderId): void { $this->selectedOrderId = $orderId; } public function cancelOrder(int $orderId, CancelOrderAction $action): void { $order = Order::findOrFail($orderId); $this->authorize('cancel', $order); $action->execute($order); session()->flash('status', 'Order #' . $order->id . ' has been cancelled.'); } public function render() { $orders = Order::with(['stall', 'orderItems.foodItem'])->where('user_id', auth()->id())->latest()->get(); $selectedOrder = $this->selectedOrderId ? $orders->firstWhere('id', $this->selectedOrderId) : $orders->first(); return view('livewire.student.my-orders', ['orders' => $orders, 'selectedOrder' => $selectedOrder]); } }